"""Phase 8.6: the report's figure set, regenerated by scripts (plan §8.6).

    python -m analysis.figures

Draws the two figures that no other script makes and writes the manifest reports/figures/README.md,
which lists every report figure with the command that regenerates it and whether the file exists.

  per_relation_f1.png   per-relation F1 of the report-set experiments on each test set, geometric
                        labels, val-tuned thresholds, with the 95% bootstrap CI over diagrams
                        (from reports/tables/phase8_summary.csv, analysis.phase8)
  headline_table.png    queries solved by both / fine-tune only / probe only / neither per test set
                        (from reports/tables/headline_table.csv, analysis.headline_table)
"""

from __future__ import annotations

import argparse
import csv
from pathlib import Path

import numpy as np

from experiments.run import REPO_ROOT, load_config

BAR_EXPERIMENTS = [("sq_probe", "linear probe"), ("sq_finetune_colab", "fine-tune (7.2)"),
                   ("sq_finetune_synth10k", "+ 10k synthetic (7.3)"), ("sq_selftrain_control", "Part B control"),
                   ("sq_ablation_dinov2", "DINOv2-L (7.5)")]
UNITS = [("geometry3k_test", "Geometry3K test"), ("pgdp5k_heldout", "PGDP5K held-out"), ("synth_extrap", "synthetic extrapolation")]
# the plan's list (§8.6): file(s) -> the command that regenerates them
MANIFEST = [
    ("loader check", ["loader_check_geometry3k.png", "loader_check_pgdp5k.png", "loader_check_pgps9k.png"], "python -m data.sanity"),
    ("tolerance histograms (combined)", ["tolerance_all.png"], "python -m verifier.tolerance"),
    ("dataset examples with overlays", ["dataset_examples.png"], "python -m data.dataset --config configs/smoke.yaml --examples"),
    ("synthetic examples", ["synthetic_examples.png"], "python -m data.synthetic.check"),
    ("scaling curve (Part A)", ["scaling_square.png", "scaling.png"], "python -m analysis.phase7"),
    ("headline table", ["headline_table.png"], "python -m analysis.figures (data: python -m analysis.headline_table)"),
    ("per-relation F1 bars per test set", ["per_relation_f1.png"], "python -m analysis.figures (data: python -m analysis.phase8)"),
    ("attention maps", ["attention_grid.png"], "python -m analysis.attention_maps"),
    ("audit examples: asserted-but-false, true-but-unmarked (datasets)", ["audit_geometry3k_asserted_not_geometric.png",
                                                                        "audit_geometry3k_geometric_not_asserted.png"], "python -m verifier.audit"),
    ("audit examples with the model's answer", ["audit_examples_model.png"], "python -m analysis.asserted_vs_geometric"),
    ("error analysis: accuracy vs verifier margin; F1 by points and segment length", ["error_margin.png", "error_breakdowns.png"],
     "python -m analysis.error_analysis"),
]


def read_csv(path: Path) -> list[dict]:
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def _f(x) -> float:
    return float("nan") if x in (None, "") else float(x)


def per_relation_figure(summary: list[dict], vocab: list[str], out: Path, experiments=BAR_EXPERIMENTS, units=UNITS) -> None:
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    rows = {(r["experiment"], r["unit"]): r for r in summary if r["label_set"] == "geometric" and r["operating"] == "tuned"}
    exps = [(e, lab) for e, lab in experiments if any((e, u) in rows for u, _ in units)]
    fig, axes = plt.subplots(len(units), 1, figsize=(8.5, 2.9 * len(units)), sharex=True, squeeze=False)
    width = 0.8 / max(len(exps), 1)
    x = np.arange(len(vocab))
    for ax, (u, label) in zip(axes[:, 0], units):
        for k, (e, lab) in enumerate(exps):
            r = rows.get((e, u))
            if r is None:
                continue
            f1 = np.array([_f(r.get(f"f1_{v}")) for v in vocab])
            lo = np.array([_f(r.get(f"f1_lo_{v}")) for v in vocab])
            hi = np.array([_f(r.get(f"f1_hi_{v}")) for v in vocab])
            err = np.vstack([np.nan_to_num(f1 - lo), np.nan_to_num(hi - f1)])
            ax.bar(x + (k - (len(exps) - 1) / 2) * width, np.nan_to_num(f1), width, yerr=err, capsize=2, label=lab,
                   error_kw={"lw": 0.7})
        ax.set_ylim(0, 1.02)
        ax.set_ylabel("F1 (geometric)")
        ax.set_title(label, fontsize=9)
        ax.grid(axis="y", alpha=0.3)
    axes[-1, 0].set_xticks(x, vocab)
    axes[0, 0].legend(fontsize=7, ncol=len(exps))
    fig.suptitle("Per-relation F1 at val-tuned thresholds, seed-mean with 95% bootstrap CI over diagrams", fontsize=9)
    fig.tight_layout()
    out.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(out, dpi=150)
    plt.close(fig)


def headline_figure(headline: list[dict], out: Path, units=UNITS) -> None:
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    rows = {r["unit"]: r for r in headline if r["seed"] == "mean" and r["level"] == "query" and r["relation"] == "all"}
    cats = [("both", "solved by both", "#4c72b0"), ("finetune_only", "fine-tune only", "#55a868"),
            ("probe_only", "probe only", "#dd8452"), ("neither", "neither", "#c44e52")]
    fig, ax = plt.subplots(figsize=(8.0, 2.4 + 0.5 * len(units)))
    ys = np.arange(len(units))[::-1]
    for y, (u, label) in zip(ys, units):
        r = rows.get(u)
        if r is None:
            continue
        left = 0.0
        for c, lab, col in cats:
            share = _f(r[f"share_{c}"])
            ax.barh(y, share, left=left, color=col, label=lab if y == ys[0] else None)
            if share > 0.04:
                ax.text(left + share / 2, y, f"{100 * share:.0f}%", ha="center", va="center", fontsize=8, color="white")
            left += share
    ax.set_yticks(ys, [f"{label}\n(n = {int(float(rows[u]['n'])):,})" if u in rows else label for u, label in units], fontsize=8)
    ax.set_xlim(0, 1)
    ax.set_xlabel("share of test queries (every applicable decision right; geometric labels, val-tuned thresholds)", fontsize=8)
    probe, ft = (headline[0]["probe"], headline[0]["finetune"]) if headline else ("probe", "fine-tune")
    ax.set_title(f"Queries solved by the linear probe ({probe}) and the fine-tune ({ft})", fontsize=9)
    ax.legend(fontsize=7, ncol=4, loc="lower center", bbox_to_anchor=(0.5, 1.12))
    fig.tight_layout()
    out.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(out, dpi=150)
    plt.close(fig)


def manifest(figures_dir: Path) -> str:
    lines = ["# Report figures (plan §8.6)", "", "Every figure is written by a script; nothing is hand-edited. "
             "Regenerate with the command in the last column (from the repository root, inside the virtualenv).", "",
             "| figure | file(s) | present | regenerate |", "|---|---|---|---|"]
    for name, files, cmd in MANIFEST:
        present = ", ".join("yes" if (figures_dir / f).exists() else f"MISSING" for f in files)
        lines.append(f"| {name} | {', '.join(f'`{f}`' for f in files)} | {present} | `{cmd}` |")
    return "\n".join(lines + [""])


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.parse_args(argv)
    cfg = load_config(REPO_ROOT / "configs" / "base.yaml")
    tables, figs = REPO_ROOT / cfg["paths"]["tables"], REPO_ROOT / cfg["paths"]["figures"]
    from data.queries import vocabulary
    vocab = vocabulary(cfg)
    per_relation_figure(read_csv(tables / "phase8_summary.csv"), vocab, figs / "per_relation_f1.png")
    headline_figure(read_csv(tables / "headline_table.csv"), figs / "headline_table.png")
    text = manifest(figs)
    (figs / "README.md").write_text(text)
    print(text)
    print(f"-> {figs}/per_relation_f1.png, headline_table.png, README.md")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
